def setUp(self):
        self.tmpdir = tempfile.TemporaryDirectory()
        self.db_path = Path(self.tmpdir.name) / "mnemosyne.db"
        # Make sure no opt-out env var leaks in from the test runner.
        self._saved_env = os.environ.pop("MNEMOSYNE_AUTO_MIGRATE", None)
        # Reset module-level thread-local connections between tests.
        tl = getattr(beam_module, "_thread_local", None)
        if tl is not None and hasattr(tl, "conn") and tl.conn is not None:
            try:
                tl.conn.close()
            except Exception:
                pass
            tl.conn = None
            if hasattr(tl, "db_path"):
                tl.db_path = None

def tearDown(self):
        if self._saved_env is not None:
            os.environ["MNEMOSYNE_AUTO_MIGRATE"] = self._saved_env
        else:
            os.environ.pop("MNEMOSYNE_AUTO_MIGRATE", None)
        # Reset thread-local connections again so the next test gets a fresh state.
        tl = getattr(beam_module, "_thread_local", None)
        if tl is not None and hasattr(tl, "conn") and tl.conn is not None:
            try:
                tl.conn.close()
            except Exception:
                pass
            tl.conn = None
            if hasattr(tl, "db_path"):
                tl.db_path = None
        self.tmpdir.cleanup()

def tearDown(self):
        import os
        for suffix in ("", ".pre_e6_backup"):
            try:
                os.unlink(str(self.tmp.name) + suffix)
            except OSError:
                pass

def tearDown(self):
        import os
        if self._saved_env is None:
            os.environ.pop("MNEMOSYNE_DATA_DIR", None)
        else:
            os.environ["MNEMOSYNE_DATA_DIR"] = self._saved_env

        for path in (self.tmp.name, str(self.canon_db), str(self.canon_db) + ".pre_e6_backup"):
            try:
                os.unlink(path)
            except OSError:
                pass

        import hermes_plugin
        hermes_plugin._memory_instance = None
        hermes_plugin._current_session_id = None
        hermes_plugin._triple_store = None

def tearDown(self):
