def patterns(monkeypatch):
    def _set(entries):
        compiled = []
        for entry in entries:
            if entry.endswith("/*"):
                compiled.append((entry[:-2], True))
            else:
                compiled.append((entry, False))
        monkeypatch.setattr(_utils_api, "whitelist_patterns", compiled)

    return _set

