def live(request, tmp_path):
    """Backend + collection on the live server, namespaced per test."""
    namespace = "conf_" + request.node.name.replace("[", "_").replace("]", "")[:40]
    backend = PgVectorBackend()
    created = []

    def make(path, name="drawers", create=True, ns=namespace, dsn=LIVE_DSN, backend_=None):
        b = backend_ or backend
        ref = PalaceRef(id=str(path), local_path=str(path), namespace=ns)
        col = b.get_collection(
            palace=ref, collection_name=name, create=create, options={"dsn": dsn, "namespace": ns}
        )
        created.append(col)
        return col

    yield backend, make, namespace
    for col in created:
        try:
            col._client.drop_table(col._table)
        except Exception:
            pass
    backend.close()

def diverged(monkeypatch):
    """A palace whose vector index is known-diverged, probe counted."""
    from mempalace import mcp_server

    probes = {"n": 0}

    def _probe():
        probes["n"] += 1

    monkeypatch.setattr(mcp_server, "_refresh_vector_disabled_flag", _probe)
    monkeypatch.setattr(mcp_server, "_vector_disabled", True)
    monkeypatch.setattr(mcp_server, "_vector_disabled_reason", REASON)
    return probes

def fixture_project(tmp_path: Path) -> Path:
    _write(tmp_path, "pkg/__init__.py", "")
    _write(tmp_path, "pkg/ranker.py", '''
        """Ranking helpers."""

        def rank_results(candidates):
            """Sort candidates by their score descending."""
            return sorted(candidates, key=lambda c: c["score"], reverse=True)

        def fuse_two_lists(a, b, k=60):
            """Merge two ranked result lists via reciprocal rank fusion."""
            scores = {}
            for rows in (a, b):
                for rank, item in enumerate(rows, 1):
                    scores[item] = scores.get(item, 0) + 1 / (k + rank)
            return sorted(scores, key=scores.get, reverse=True)
    ''')
    _write(tmp_path, "pkg/graph.py", '''
        """Graph helpers."""

        class ImportGraph:
            """Directed graph over module imports."""

            def find_cycles(self):
                """Detect strongly-connected components (Tarjan)."""
                return []

            def add_edge(self, a, b):
                """Record an import from a to b."""
                pass
    ''')
    return tmp_path

def java_project(tmp_path):
    """Create a small Java project for end-to-end indexer regression tests."""
    root = tmp_path / "javaproject"
    pkg = root / "src" / "main" / "java" / "com" / "example"
    pkg.mkdir(parents=True)

    (pkg / "Calculator.java").write_text(
        textwrap.dedent("""\
        package com.example;

        import java.util.ArrayList;
        import java.util.List;

        /** A toy calculator. */
        public class Calculator {
            private final List<Integer> history = new ArrayList<>();

            public int add(int a, int b) {
                int result = a + b;
                history.add(result);
                return result;
            }

            public int sub(int a, int b) {
                return a - b;
            }
        }
        """)
    )

    (pkg / "Main.java").write_text(
        textwrap.dedent("""\
        package com.example;

        public class Main {
            public static void main(String[] args) {
                Calculator c = new Calculator();
                System.out.println(c.add(1, 2));
            }
        }
        """)
    )

    return root

