def temp_mcp_file():
    """Create a temporary MCP server file for testing"""
    def _create(content: str, suffix: str = '.ts') -> Path:
        fd, path = tempfile.mkstemp(suffix=suffix, prefix='mcp_test_')
        os.write(fd, content.encode('utf-8'))
        os.close(fd)
        return Path(path)
    return _create

