def cleanup_redis(self):
        """Clean up Redis cache before each test."""
        # Clear tenant plan cache using BillingService key prefix
        try:
            keys = redis_client.keys(f"{self.PLAN_CACHE_KEY_PREFIX}*")
            if keys:
                redis_client.delete(*keys)
        except Exception:
            pass  # Redis might not be available in some test environments
        yield
        # Clean up after test
        try:
            keys = redis_client.keys(f"{self.PLAN_CACHE_KEY_PREFIX}*")
            if keys:
                redis_client.delete(*keys)
        except Exception:
            pass

def fix_method_view_issue(monkeypatch):
    if not hasattr(builtins, "MethodView"):
        monkeypatch.setattr(builtins, "MethodView", MethodView, raising=False)

def _no_network(monkeypatch):
    """防止测试意外发出真实网络请求（可按需在单个测试中移除）。"""
    import socket

    def _guard(*args, **kwargs):
        raise RuntimeError("Tests must not make real network calls")

    monkeypatch.setattr(socket, "create_connection", _guard)

