                "topic": "Child2",
                "children": [],
                "parents": [0],
                "metadata": {"uuid": "test-uuid-2"},
            },
        },
        "root_id": 0,
        "metadata": {
            "provider": "openai",
            "model": "gpt-4",
            "temperature": 0.7,
            "created_at": "2024-01-01T00:00:00+00:00",
        },
    }
