    """Import fun-doc/web.py with its sibling-imports resolvable."""
    monkeypatch.setenv("FUNDOC_DASHBOARD", "false")
    monkeypatch.syspath_prepend(str(FUN_DOC_DIR))
    if "web" in sys.modules:
