def ghidra(live_benchmark_ghidra: str):
    """A thin client bound to the DEDICATED instance.

    `benchmark/ghidra_bridge.py` resolves its URL from `GHIDRA_SERVER_URL` at
    IMPORT time, so it cannot be re-pointed by setting the env var in a
    fixture. This client exists so no call in this tier can accidentally
    inherit the module-level default of 8089.
    """
    import requests

    class Client:
        def __init__(self, base: str):
            self.base = base
            self.session = requests.Session()

        def get(self, path: str, **params) -> Any:
            r = self.session.get(
                f"{self.base}{path}",
                params={k: v for k, v in params.items() if v is not None},
                timeout=120,
            )
            r.raise_for_status()
            try:
                return r.json()
            except ValueError:
                return r.text

        def post(self, path: str, body: dict | None = None, **params) -> Any:
            r = self.session.post(
                f"{self.base}{path}",
                json=body or {},
                params={k: v for k, v in params.items() if v is not None},
                timeout=300,
            )
            r.raise_for_status()
            try:
                return r.json()
            except ValueError:
                return r.text

    return Client(live_benchmark_ghidra)

def program_functions(ghidra, benchmark_program):
    resp = ghidra.get("/list_functions", program=benchmark_program, limit=100000)
    fns = resp.get("functions") if isinstance(resp, dict) else None
    if not fns:
        pytest.skip(
            f"{benchmark_program} has no functions on the dedicated instance -- "
            f"import Benchmark.dll and let auto-analysis finish first"
        )
    return {str(f["address"]).lower().replace("0x", ""): f.get("name") or "" for f in fns}

