                            }
                        },
                    }
                }
            },
        }

def director(self, basic_openapi_30_spec):
        spec = SchemaPath.from_dict(basic_openapi_30_spec)
        return RequestDirector(spec)

def path_route(self):
        return HTTPRoute(
            path="/api/v1/users/{id}/profile",
            method="GET",
            operation_id="get_user_profile",
            parameters=[
                ParameterInfo(
                    name="id",
                    location="path",
                    required=True,
                    schema={"type": "string"},
                )
            ],
            flat_param_schema={
                "type": "object",
                "properties": {"id": {"type": "string"}},
                "required": ["id"],
            },
            parameter_map={"id": {"location": "path", "openapi_name": "id"}},
        )

def _require_npx():
    if shutil.which("npx") is None:
        pytest.skip("npx not found on PATH — install Node.js to run conformance tests")

def captured_calls(monkeypatch):
    """Pretend the hermes CLI exists; capture each subprocess invocation."""
    monkeypatch.setattr(cron, "_HERMES_BIN", "/usr/bin/hermes")
    calls: list[tuple[list[str], dict]] = []

    def fake_run(cmd, **kwargs):
        calls.append((cmd, kwargs))
        return _FakeCompleted(returncode=0)

    monkeypatch.setattr(cron.subprocess, "run", fake_run)
    return calls

def hermes_home(tmp_path: Path, monkeypatch) -> Path:
    monkeypatch.setenv("HERMES_HOME", str(tmp_path))
    return tmp_path

def hermes_home(tmp_path: Path, monkeypatch) -> Path:
    monkeypatch.setenv("HERMES_HOME", str(tmp_path))
    return tmp_path

