async def fake_llm_server():
    """A pytest fixture to run a fake server and capture requests."""
    last_request = {"body": None}

    async def fake_openai_handler(request):
        """Fake OpenAI API endpoint that captures the request body."""
        last_request["body"] = await request.json()

        # Return a minimal valid OpenAI-style response
        response = {
            "id": "chatcmpl-test123",
            "object": "chat.completion",
            "created": 1234567890,
            "model": "gpt-4o",
            "choices": [
                {
                    "index": 0,
                    "message": {
                        "role": "assistant",
                        "content": '{"keystrokes": "echo \\"Hello World\\"", "duration": 1, "task_complete": true}'
                    },
                    "finish_reason": "stop"
                }
            ],
            "usage": {
                "prompt_tokens": 10,
                "completion_tokens": 20,
                "total_tokens": 30
            }
        }
        return web.json_response(response)

    app = web.Application()
    app.router.add_post('/v1/chat/completions', fake_openai_handler)
    runner = web.AppRunner(app)
    await runner.setup()
    site = web.TCPSite(runner, 'localhost', 0)  # Use port 0 for a random available port
    await site.start()
    port = site._server.sockets[0].getsockname()[1]

    def get_last_request():
        return last_request["body"]

    yield {"port": port, "get_last_request": get_last_request}

    await runner.cleanup()

async def fake_llm_server():
    """A pytest fixture to run a fake LLM server and capture requests."""
    call_count = {"count": 0}

    async def fake_openai_handler(request):
        """Fake OpenAI API endpoint that returns deterministic responses."""
        request_data = await request.json()

        # Increment call count
        call_count["count"] += 1

        # Get the model from the request
        model = request_data.get("model", "gpt-4")

        print(f"[FAKE SERVER] Received call #{call_count['count']} for model: {model}")

        # First call: Create the hello.txt file
        if call_count["count"] == 1:
            response = {
                "id": "chatcmpl-fake-1",
                "object": "chat.completion",
                "created": 1234567890,
                "model": model,
                "choices": [{
                    "index": 0,
                    "message": {
                        "role": "assistant",
                        "content": None,
                        "tool_calls": [{
                            "id": "call_fake_1",
                            "type": "function",
                            "function": {
                                "name": "str_replace_editor",
                                "arguments": json.dumps({
                                    "command": "create",
                                    "path": "/app/hello.txt",
                                    "file_text": "Hello, world!",
                                    "security_risk": "LOW"
                                })
                            }
                        }]
                    },
                    "finish_reason": "tool_calls"
                }],
                "usage": {
                    "prompt_tokens": 100,
                    "completion_tokens": 50,
                    "total_tokens": 150
                }
            }
        # Second call: Finish the task
        elif call_count["count"] == 2:
            response = {
                "id": "chatcmpl-fake-2",
                "object": "chat.completion",
                "created": 1234567891,
                "model": model,
                "choices": [{
                    "index": 0,
                    "message": {
                        "role": "assistant",
                        "content": None,
                        "tool_calls": [{
                            "id": "call_fake_2",
                            "type": "function",
                            "function": {
                                "name": "finish",
                                "arguments": json.dumps({
                                    "message": "Task complete. Created /app/hello.txt with 'Hello, world!'"
                                })
                            }
                        }]
                    },
                    "finish_reason": "tool_calls"
                }],
                "usage": {
                    "prompt_tokens": 120,
                    "completion_tokens": 30,
                    "total_tokens": 150
                }
            }
        else:
            # Fallback for any additional calls - return a simple text response
            response = {
                "id": f"chatcmpl-fake-{call_count['count']}",
                "object": "chat.completion",
                "created": 1234567890 + call_count["count"],
                "model": model,
                "choices": [{
                    "index": 0,
                    "message": {
                        "role": "assistant",
                        "content": "Task already completed."
                    },
                    "finish_reason": "stop"
                }],
                "usage": {
                    "prompt_tokens": 100,
                    "completion_tokens": 10,
                    "total_tokens": 110
                }
            }

        return web.json_response(response)

    app = web.Application()
    app.router.add_post('/v1/chat/completions', fake_openai_handler)
    runner = web.AppRunner(app)
    await runner.setup()
    # Listen on all interfaces (0.0.0.0) so Docker containers can access it
    site = web.TCPSite(runner, '0.0.0.0', 0)  # Use port 0 for a random available port
    await site.start()
    port = site._server.sockets[0].getsockname()[1]

    def get_call_count():
        return call_count["count"]

    print(f"\n[FAKE SERVER] Started on http://localhost:{port}/v1")

    yield {"port": port, "get_call_count": get_call_count}

    await runner.cleanup()
    print("[FAKE SERVER] Stopped")

