def pattern(self, regexp_data):
        matching = [
            p for p in regexp_data["patterns"]
            if "〔" in p.get("pattern", "") and "〕" in p.get("pattern", "")
        ]
        assert matching, "tortoise shell pattern not found in regexp_v09.json"
        return re.compile(matching[0]["pattern"])

def pattern(self, regexp_data):
        # Find the pattern that includes 'BGM' as a keyword
        matching = [
            p for p in regexp_data["patterns"]
            if "BGM" in p.get("pattern", "") and "歓声" in p.get("pattern", "")
        ]
        assert matching, "HI keyword pattern not found in regexp_v09.json"
        return re.compile(matching[0]["pattern"])

def deep_exc_info() -> ExcInfo:
    """Create a deeper call stack for testing max_frames."""

    def level_5():
        local_var_5 = "level_5_value"  # noqa: F841
        raise ValueError("Deep stack error")  # noqa: EM101

    def level_4():
        local_var_4 = "level_4_value"  # noqa: F841
        level_5()

    def level_3():
        local_var_3 = "level_3_value"  # noqa: F841
        level_4()

    def level_2():
        local_var_2 = "level_2_value"  # noqa: F841
        level_3()

    def level_1():
        local_var_1 = "level_1_value"  # noqa: F841
        level_2()

    try:
        level_1()
    except ValueError:
        return sys.exc_info()

def record_with_deep_exception(self, deep_exc_info: ExcInfo):
        return logging.LogRecord(
            name="test",
            level=logging.ERROR,
            pathname="test",
            lineno=1,
            msg="deep stack test",
            args=None,
            exc_info=deep_exc_info,
        )

