def hf_token():
    token = os.environ.get("HUGGINGFACE_TOKEN")
    if not token:
        pytest.skip("HUGGINGFACE_TOKEN environment variable is not set")
    return token

def hf_endpoint():
    endpoint = os.environ.get("HUGGINGFACE_ENDPOINT")
    if not endpoint:
        pytest.skip("HUGGINGFACE_ENDPOINT environment variable is not set")
    return endpoint

def hf_chat_target(hf_token, hf_endpoint, sqlite_instance) -> OpenAIChatTarget:
    return OpenAIChatTarget(
        endpoint=hf_endpoint,
        api_key=hf_token,
        model_name=DEFAULT_HF_MODEL,
        max_tokens=30,
    )

def hf_response_target(hf_token, hf_endpoint, sqlite_instance) -> OpenAIResponseTarget:
    return OpenAIResponseTarget(
        endpoint=hf_endpoint,
        api_key=hf_token,
        model_name=DEFAULT_HF_MODEL,
        max_output_tokens=30,
    )

def gpt2_model() -> GPT2LMHeadModel:
    """Load GPT-2 model once for all tests in this module."""
    return GPT2LMHeadModel.from_pretrained("gpt2").eval()

def config_files(self) -> list[str]:
        """Return list of all YAML config files shipped with GCG."""
        configs_dir = os.path.normpath(CONFIGS_DIR)
        if not os.path.isdir(configs_dir):
            pytest.skip(f"Config directory not found: {configs_dir}")
        return [os.path.join(configs_dir, f) for f in os.listdir(configs_dir) if f.endswith(".yaml")]

