def mock_distribution():
    original_distribution = importlib.metadata.distribution

    def side_effect(package_name):
        if package_name == "audio-separator":
            mock_dist = MagicMock()
            mock_dist.version = "0.42.0"
            return mock_dist
        return original_distribution(package_name)

    with patch("importlib.metadata.distribution", side_effect=side_effect):
        yield

def driver() -> Iterator[RigolDG1022Z]:
    awg_driver = RigolDG1022Z(
        VisaConfig(
            visa_resource=VISA_RESOURCE,
            visa_backend=VISA_BACKEND,
        )
    )
    opened = False
    try:
        awg_driver.open()
        opened = True
        yield awg_driver
    finally:
        if opened:
            _shutdown_outputs(awg_driver)
        awg_driver.close()

def rigol_visa_cls() -> Iterator[MagicMock]:
