def returns():
    rng = np.random.default_rng(0)
    true_cov = [[1.0, 0.5, 0.3], [0.5, 1.0, 0.4], [0.3, 0.4, 1.0]]
    return rng.multivariate_normal(mean=[0, 0, 0], cov=true_cov, size=300)

