def tok():
    transformers = pytest.importorskip("transformers")
    # CACHE-ONLY (codex r7 #1). These enforcement tests NEVER hit the network: the
    # offline-vs-corrupt decision is made entirely by cache presence, so there is no
    # live download to fail on a firewalled/offline CI and no wrapped-exception
    # classification to get wrong. NOT cached -> skip (genuinely unavailable);
    # cached -> load with ``local_files_only=True`` so a partial/corrupt cache raises
    # immediately (the test FAILS) instead of silently triggering a download.
    if not _tokenizer_in_cache():
        pytest.skip(
            f"tokenizer {_TOKENIZER_MODEL}@{_TOKENIZER_REVISION[:8]} not in the local "
            "HF cache — gemma4 enforcement tests are cache-only (no network). "
            "Pre-cache the tokenizer to run them."
        )
    return transformers.AutoTokenizer.from_pretrained(
        _TOKENIZER_MODEL, revision=_TOKENIZER_REVISION, local_files_only=True
    )

def patched_textmodel(_restore_install_state, monkeypatch):
    """Install the fix over a stub TextModel whose original sanitize mimics
    mlx-lm. Yields a callable ``run(weights)`` invoking the patched method."""
    from mlx_lm.models import qwen3_5 as q

    # Clean slate on the real module attributes the patch stashes onto.
    nsf.uninstall_qwen3_5_norm_shift_fix()
    for attr in (
        "_RAPID_MLX_ORIG_TEXTMODEL_SANITIZE",
        "_RAPID_MLX_NORM_SHIFT_INSTALLED",
    ):
        if hasattr(q, attr):
            monkeypatch.delattr(q, attr, raising=False)

    class _StubTextModel:
        sanitize = _mlx_lm_mimic_sanitize

    monkeypatch.setattr(q, "TextModel", _StubTextModel)

    nsf.install_qwen3_5_norm_shift_fix()

    fake_self = types.SimpleNamespace(
        args=types.SimpleNamespace(tie_word_embeddings=False)
    )

    def run(weights):
        return q.TextModel.sanitize(fake_self, weights)

    yield run
    nsf.uninstall_qwen3_5_norm_shift_fix()

