def bridge(monkeypatch):
    """A real, begun IGlobal (live bridge loop) that is always torn down."""
    glbs = []

    def make(cfg=None, **kw):
        glb = _real_global(monkeypatch, cfg or {'connection_string': 'iggy:laser@localhost:8090'}, **kw)
        glbs.append(glb)
        return glb

    yield make
    for glb in glbs:
        glb.endGlobal()

