    monkeypatch.setenv("BERNSTEIN_AUTH_DISABLED", "1")
    # Default: flag off so the off-by-default test sees the disabled payload.
    monkeypatch.delenv("BERNSTEIN_BOT_TOOLS_ENABLED", raising=False)
    app = create_app(jsonl_path=tmp_path / "tasks.jsonl")
    return TestClient(app)

def _pin_audit_key(monkeypatch):
    # The audit-verify path loads the install audit key directly, so pin it.
    monkeypatch.setattr("bernstein.core.security.audit.load_or_create_audit_key", lambda *a, **k: b"k" * 32)

def _pin_audit_key(monkeypatch):
    # Pin the install audit key so the CLI reconstructs with a known key.
    monkeypatch.setattr(grants, "_audit_key", lambda: b"k" * 32)

def _assume_patched_tarfile_filter(request: pytest.FixtureRequest, monkeypatch: pytest.MonkeyPatch) -> None:
    # Tests that exercise the real version matrix opt out via the marker;
    # everything else gets the check pinned to True so round-trip / correctness
    # tests are independent of the host's CPython patch level.
    if request.node.get_closest_marker("raw_tarfile_filter"):
        return
    monkeypatch.setattr(_vmmonitor, "_tarfile_data_filter_is_patched", lambda: True)

