def passthrough_to_thread(self):
        """Make asyncio.to_thread call the function directly."""

        async def _passthrough(func, *args, **kwargs):
            return func(*args, **kwargs)

        with patch('asyncio.to_thread', side_effect=_passthrough):
            yield

