def build_mymod():
    archive = MYMOD_PATH.join("build", "wasi", "libmymod.a")
    sources = MYMOD_PATH.listdir("*.c") + MYMOD_PATH.listdir("*.h")
    if archive.exists() and all(archive.mtime() >= src.mtime() for src in sources):
        return
    subprocess.run(
        ["make", "TARGET=wasi"],
        cwd=str(MYMOD_PATH),
        check=True,
    )

