def kimi_tokenizer():
    """Get the Kimi K2.6 tokenizer (cached per module)."""
    try:
        return get_tokenizer(KIMI_K26_MODEL)
    except ModuleNotFoundError as e:
        if "Kimi-K2" in str(e):
            pytest.skip(f"K2.6 tokenizer has HF module import bug: {e}")
        raise

