def aapl_holders(self):
        holders = []
        # 91% genuine (small change relative to shares)
        for i in range(910):
            holders.append(_make_holder(f"Genuine{i}", 10_000, 500))
        # 5% new_full
        for i in range(50):
            holders.append(_make_holder(f"New{i}", 1_000, 1_000))
        # 4% exited
        for i in range(40):
            holders.append(_make_holder(f"Exited{i}", 0, -1_000))
        return holders

def nflx_holders(self):
        holders = []
        # 99% new_full (change == shares)
        for i in range(5365):
            holders.append(_make_holder(f"New{i}", 1_000, 1_000))
        # 1% genuine
        for i in range(50):
            holders.append(_make_holder(f"Genuine{i}", 10_000, 200))
        return holders

def mock_analyzer(self, monkeypatch):
        analyzer = SingleStockAnalyzer("fake_key")

        def mock_profile(symbol):
            return {
                "companyName": "Test Corp",
                "sector": "Technology",
                "mktCap": 1_000_000_000,
            }

        def mock_holders(symbol):
            holders = []
            # Q4 2025: 100 genuine holders + 10 new_full + 5 exited
            for i in range(100):
                holders.append({
                    "holder": f"Fund{i}",
                    "shares": 10_000 + i * 100,
                    "change": 500 if i % 2 == 0 else -200,
                    "dateReported": "2025-12-31",
                })
            for i in range(10):
                holders.append({
                    "holder": f"NewFund{i}",
                    "shares": 5_000,
                    "change": 5_000,
                    "dateReported": "2025-12-31",
                })
            for i in range(5):
                holders.append({
                    "holder": f"ExitFund{i}",
                    "shares": 0,
                    "change": -3_000,
                    "dateReported": "2025-12-31",
                })
            # Q3 2025: 95 holders (subset)
            for i in range(95):
                holders.append({
                    "holder": f"Fund{i}",
                    "shares": 9_500 + i * 100,
                    "change": 300,
                    "dateReported": "2025-09-30",
                })
            return holders

        monkeypatch.setattr(analyzer, "get_company_profile", mock_profile)
        monkeypatch.setattr(analyzer, "get_institutional_holders", mock_holders)
        return analyzer

def single_iteration_history() -> dict:
    """History with only 1 iteration."""
    return {
        "strategy_id": "single_test",
        "iterations": [
            make_iteration(1, make_eval(45)),
        ],
    }

def tail_risk_history() -> dict:
    """History where tail_risk triggers via high drawdown.

    Condition: max_drawdown_pct > 35.
    """
    ev = make_eval(40, max_drawdown_pct=42.0, risk_mgmt_score=4)
    return {
        "strategy_id": "risky_strat",
        "iterations": [
            make_iteration(1, ev, "Initial run"),
        ],
    }

def abandon_history() -> dict:
    """History with 3+ iterations, latest score < 30, monotonically non-increasing last 3.

    Scores: 28, 25, 22 -- declining and all below 30.
    """
    evals = [
        make_eval(28),
        make_eval(25),
        make_eval(22),
    ]
    return {
        "strategy_id": "hopeless_strat",
        "iterations": [make_iteration(i + 1, ev, f"Attempt {i + 1}") for i, ev in enumerate(evals)],
    }

