def skip_if_unexposable():
    """Skip when a trace failed because the server's runtime couldn't publish its port to the
    host — a prime sandbox whose region doesn't support port exposure (a known infra limit, not
    a code bug). subprocess/docker share the host network, so they never hit this."""

    def _skip(trace) -> None:
        if any("port exposure" in str(e) for e in trace.errors):
            pytest.skip(
                "runtime can't publish a port to the host (pin a prime region that supports port exposure)"
            )

    return _skip

def harness_supports():
    """Read a capability flag (e.g. `SUPPORTS_TASK_TOOLS`, `SUPPORTS_USER_SIM`) off an harness
    by id — the matrix tests use it to decide whether a harness/task pairing should run, be
    rejected, or be skipped."""
    from verifiers.v1.loaders import load_harness

    def _supports(harness_id: str, flag: str) -> bool:
        harness = load_harness(
            EvalConfig.model_validate({"harness": {"id": harness_id}}).harness
        )
        return getattr(harness, flag)

    return _supports

def fake_judge_model(monkeypatch):
    """Fake the judge's model call, recording each prompt for assertions. Text calls reply
    "yes" iff "Paris" appears in the response block of the rendered prompt; structured
    (`schema`) calls verdict each `- name: text` criteria line "yes" iff it mentions Paris."""
    prompts: list[str] = []

    async def fake_complete(
        self, messages, *, trace=None, schema=None, parse=None, **sampling
    ):
        prompts.append(messages)
        if schema is not None:
            verdicts = [
                {"name": name, "verdict": "yes" if "Paris" in text else "no"}
                for name, text in re.findall(r"^- ([^:]+): (.+)$", messages, re.M)
            ]
            response = JudgeResponse(
                text=json.dumps(verdicts),
                parsed=schema.model_validate({"verdicts": verdicts}),
            )
        else:
            response = JudgeResponse(
                text="yes" if "Paris" in messages.split("Response:")[-1] else "no"
            )
        if parse is not None:
            response.parsed = parse(response)
        if trace is not None:
            trace.record_judge(response)
        return response

    monkeypatch.setattr(Judge, "complete", fake_complete)
    return prompts

def _fake_lama(self, monkeypatch: pytest.MonkeyPatch):
        from remove_ai_watermarks import region_eraser

        class _In:
            def __init__(self, name: str, shape: list[int]):
                self.name = name
                self.shape = shape

        class _FakeSession:
            def get_inputs(self):
                return [_In("image", [1, 3, 512, 512]), _In("mask", [1, 1, 512, 512])]

            def run(self, _outputs, feeds):
                # Identity inpaint: echo the image tensor (1,3,size,size) back.
                return [feeds["image"]]

        monkeypatch.setattr(region_eraser, "lama_available", lambda: True)
        monkeypatch.setattr(region_eraser, "_get_lama_session", lambda: _FakeSession())

